/* Reading Telegraph pages written in Telepatch's format (D-090, D-091).
 * Pure functions: no DOM, no network, so the build and the tests use them too.
 *
 *   index page : prose, then a <ul> of entries "Title — 2026-11-18 · 6 min · tags" <br> excerpt,
 *                then the marker line "Index generated by Telepatch. byline=… [collection=extra]"
 *   post page  : <aside> tag line, optional <blockquote> standfirst, body,
 *                provenance line, then <hr> + <pre> colophon starting "heavymap-journey/1"
 */

export const API = "https://api.telegra.ph";
export const MASTER_MARK = "Index generated by Telepatch.";
export const COLOPHON_MARK = "heavymap-journey/1";
const ENTRY_META = /(\d{4}-\d{2}-\d{2})(?:\s*[·,.\s]\s*(\d+)\s*min)?(?:\s*[·,.\s]\s*(.+))?/;

export const nodeText = (n) =>
  typeof n === "string" ? n : (n?.children ?? []).map(nodeText).join("");

/** Telegraph page path from a telegra.ph URL (null for anything else). */
export function telegraphPath(href) {
  try {
    const u = new URL(href, "https://telegra.ph");
    if (!/^(www\.)?telegra\.ph$/i.test(u.hostname)) return null;
    const p = u.pathname.replace(/^\/+|\/+$/g, "");
    return p && !p.includes("/") ? p : null;
  } catch {
    return null;
  }
}

/** Entries of an index page, in page order (newest first as written). */
export function parseIndex(content = []) {
  const list = content.find((n) => n?.tag === "ul");
  const intro = [];
  const footer = [];
  let seen = false;
  for (const n of content) {
    if (n === list) { seen = true; continue; }
    if (nodeText(n).includes(MASTER_MARK)) continue;
    if (nodeText(n).trim() === "Nothing here yet.") continue;
    (seen ? footer : intro).push(n);
  }
  const entries = [];
  for (const li of list?.children ?? []) {
    const kids = li?.children ?? [];
    const a = kids.find((k) => k?.tag === "a" && k.attrs?.href);
    if (!a) continue;
    const br = kids.findIndex((k) => k?.tag === "br");
    const head = (br < 0 ? kids : kids.slice(0, br)).filter((k) => typeof k === "string").join("");
    const excerpt = br < 0 ? "" : kids.slice(br + 1).map(nodeText).join("").trim();
    const m = ENTRY_META.exec(head);
    const tags = (m?.[3] ?? "").split(",").map((t) => t.trim()).filter(Boolean);
    entries.push({
      title: nodeText(a).trim(),
      url: a.attrs.href,
      path: telegraphPath(a.attrs.href),
      date: m?.[1] ?? "",
      minutes: m?.[2] ? Number(m[2]) : 0,
      tags,
      excerpt,
    });
  }
  const markerText = content.map(nodeText).find((t) => t.includes(MASTER_MARK)) ?? "";
  return { intro, footer, entries, curated: /collection=extra/.test(markerText) };
}

/** Flatten live section/collection indexes into the newest distinct posts. */
export function recentEntries(indexes = [], collectionPaths = [], limit = 6) {
  const collections = new Set(collectionPaths);
  const posts = new Map();
  for (const { key, entries = [] } of indexes) {
    for (const entry of entries) {
      if (!entry?.path || collections.has(entry.path)) continue;
      const previous = posts.get(entry.path);
      if (!previous || (entry.date || "") > (previous.date || "")) posts.set(entry.path, { ...entry, key });
    }
  }
  return [...posts.values()]
    .sort((a, b) => (b.date || "").localeCompare(a.date || "") || a.title.localeCompare(b.title))
    .slice(0, limit);
}

/** Split a post into tags, standfirst, body and colophon fields. */
export function parsePost(content = []) {
  const nodes = [...content];
  let tags = [];
  if (nodes[0]?.tag === "aside") {
    tags = nodeText(nodes.shift()).split(",").map((t) => t.trim()).filter(Boolean);
  }
  let intro = null;
  if (nodes[0]?.tag === "blockquote") intro = nodes.shift();
  const colophon = {};
  const last = nodes[nodes.length - 1];
  if (last?.tag === "pre" && nodeText(last).startsWith(COLOPHON_MARK)) {
    nodes.pop();
    if (nodes[nodes.length - 1]?.tag === "hr") nodes.pop();
    for (const line of nodeText(last).split("\n").slice(1)) {
      const i = line.indexOf(":");
      if (i > 0) colophon[line.slice(0, i).trim()] = line.slice(i + 1).trim();
    }
  }
  const sections = nodes
    .map((n, i) => ({ n, i }))
    .filter(({ n }) => n?.tag === "h3")
    .map(({ n, i }) => ({ text: nodeText(n).trim(), index: i }));
  return { tags, intro, body: nodes, colophon, sections };
}

/* ---- safe node descriptors ---------------------------------------------- */

const OK = new Set(["a", "aside", "b", "blockquote", "br", "code", "em", "figcaption", "figure",
  "h3", "h4", "hr", "i", "img", "li", "ol", "p", "pre", "s", "strong", "u", "ul"]);

/** A URL we will put in an href or src, or null. Telegraph-relative files become absolute. */
export function safeUrl(raw, { image = false } = {}) {
  if (typeof raw !== "string" || !raw) return null;
  const s = raw.startsWith("/file/") || (image && raw.startsWith("/")) ? `https://telegra.ph${raw}` : raw;
  try {
    const u = new URL(s);
    if (image) return u.protocol === "https:" ? u.href : null;
    return u.protocol === "https:" || u.protocol === "http:" || u.protocol === "mailto:" ? u.href : null;
  } catch {
    return null;
  }
}

/**
 * Walk Telegraph nodes into plain descriptors {tag, href?, src?, children} that a renderer can
 * turn into elements without ever assigning HTML. Unknown tags keep their children (fallback);
 * iframes and videos become links.
 */
export function sanitize(nodes = [], { route = () => null } = {}) {
  const out = [];
  for (const n of nodes) {
    if (typeof n === "string") { out.push(n); continue; }
    if (!n || typeof n !== "object") continue;
    const tag = String(n.tag || "").toLowerCase();
    const kids = sanitize(n.children ?? [], { route });
    if (tag === "iframe" || tag === "video") {
      const href = safeUrl(n.attrs?.src, { image: tag === "video" });
      if (href) out.push({ tag: "a", href, children: [tag === "video" ? "Video" : "Embedded media"] });
      continue;
    }
    if (!OK.has(tag)) { out.push(...kids); continue; }
    const d = { tag, children: kids };
    if (tag === "a") {
      const href = safeUrl(n.attrs?.href);
      if (!href) { out.push(...kids); continue; }
      d.href = route(href) ?? href;
      d.internal = d.href !== href;
    }
    if (tag === "img") {
      const src = safeUrl(n.attrs?.src, { image: true });
      if (!src) continue;
      d.src = src;
    }
    out.push(d);
  }
  return out;
}

export const readingMinutes = (nodes) =>
  Math.max(1, Math.round(nodes.map(nodeText).join(" ").split(/\s+/).filter(Boolean).length / 220));

/** Fetch one page with its content; resolves { page, ms, bytes }. */
export async function getPage(path, fetchImpl = fetch) {
  const t0 = performance.now();
  const res = await fetchImpl(`${API}/getPage/${encodeURIComponent(path)}?return_content=true`);
  const text = await res.text();
  const data = JSON.parse(text);
  if (!data.ok) throw new Error(data.error || "Telegraph error");
  return { page: data.result, ms: Math.round(performance.now() - t0), bytes: text.length };
}
